from itertools import combinations

from rules import allowed


def solve(data):
    k = data["k"]
    blocked = set(data.get("blocked", []))
    jobs = [job for job in data["jobs"] if job["id"] not in blocked]

    best_ids = None
    best_value = None
    for choice in combinations(jobs, k):
        if not allowed(choice, data):
            continue
        ids = tuple(sorted(job["id"] for job in choice))
        value = sum(job["value"] for job in choice)
        if (best_value is None or value > best_value or
                (value == best_value and ids > best_ids)):
            best_ids = ids
            best_value = value

    if best_ids is None:
        return {"error": "impossible"}
    return {"selected": list(best_ids), "value": best_value}

from collections import Counter

POLICY = {"capacity": 1, "tie": "largest"}


def allowed(selected, data):
    selected = list(selected)
    ids = {job["id"] for job in selected}

    if not set(data.get("mandatory", [])).issubset(ids):
        return False
    if ids.intersection(data.get("blocked", [])):
        return False

    counts = Counter(job["group"] for job in selected)
    for group, (low, high) in data.get("quotas", {}).items():
        count = counts.get(group, 0)
        if count < low or count > high:
            return False

    ordered = sorted(selected, key=lambda job: (job["start"], job["end"], job["id"]))
    previous_end = None
    for job in ordered:
        if previous_end is not None and job["start"] < previous_end:
            return False
        previous_end = job["end"]
    return True
